static const struct KakuNote U12N[] = {
	{ "〜んです", "Short form plus んです frames a statement as an explanation of the situation — giving a reason, asking for one, or softening a request. な-adjectives and nouns need な before it: しずかなんです, がくせいなんです.", U12N0EX, 2 },
	{ "〜すぎる", "Add すぎる to a verb stem or an adjective root for \"too much\". たべすぎる is to overeat, たかすぎる is too expensive. It conjugates as a る-verb.", U12N1EX, 2 },
	{ "〜ほうがいいです", "Advice. Use the past short form for \"you should\" (ねたほうがいいです) and the negative short form for \"you should not\" (いかないほうがいいです). The past form here has nothing to do with past time.", U12N2EX, 2 },
	{ "〜ので", "Another \"because\", a shade softer and more formal than から. It attaches to short forms, with な after な-adjectives and nouns.", U12N3EX, 2 },
	{ "〜なければいけません", "Obligation: \"must\". Take the short negative, drop い, add ければいけません. The casual contraction なきゃ is everywhere in speech — べんきょうしなきゃ.", U12N4EX, 2 },
	{ "〜でしょうか", "Softens a question, adding a note of \"I wonder\". Useful when asking something you are not sure the other person can answer.", U12N5EX, 2 },
};
