static const char* const C5B[] = { "Learners meet これ, この, ここ, それ, その, そこ and so on as a list of twelve things to memorise, and it is miserable. They are not twelve things. They are two choices.", "First choice, the beginning of the word: こ is near me, そ is near you, あ is away from both of us, ど is the question — which one?", "Second choice, the ending: れ stands alone and means \"one\", の goes in front of a noun, こ/そ/あそこ is a place. Put the two together and the word builds itself.", "The one that catches people is これ against この. これ is already the noun — \"this one\". この cannot stand by itself and must have a noun after it. これはあ and このほん are both fine; この by itself is not a sentence." };
static const char* const C5S[] = { "これ / それ / あれ / どれ", "stands alone — this one, that one", "この / その / あの / どの + noun", "must be followed by a noun", "ここ / そこ / あそこ / どこ", "a place — here, there, over there" };
