static const char* const C7B[] = { "This is the whole of it. がくせいです becomes がくせいじゃないです. Nothing else in the sentence changes.", "It is worth saying what this is not: it is not how you make a verb negative. たべます does not become たべますじゃないです — verbs have their own negative, ません, which Lesson 3 covers. じゃないです is only for sentences that end in です after a noun.", "In answers it usually follows いいえ: いいえ、にほんじんじゃないです。" };
static const char* const C7S[] = { "XはYじゃないです。", "X is not Y." };
