static const char* const C9B[] = { "Japanese verbs fall into three groups, and the group decides what happens when you make the polite form. Learn the group with the verb and conjugation is automatic; learn the verb without it and you are guessing every time.", "る-verbs are the easy ones: drop る, add ます. たべる becomes たべます.", "う-verbs end in a consonant sound plus う. The last kana shifts to its i-row partner before ます: のむ becomes のみます, かく becomes かきます, はなす becomes はなします.", "And two verbs are irregular: する becomes します, くる becomes きます. べんきょうする is just a noun stuck onto する, so it follows する.", "The trap: かえる ends in る but is a う-verb. It is かえります, not かえます. It is a favourite trick question." };
static const char* const C9S[] = { "る-verb", "drop る, add ます", "う-verb", "last kana moves to the i-row, add ます", "irregular", "する→します, くる→きます" };
